mkdir -p /tmp/scratch_pricing && cat > /tmp/scratch_pricing/compare.py <<'EOF'
import csv, sys, collections
from decimal import Decimal
sys.path.insert(0, sys.argv[1])
import price as old

# Proposed single table: one row per band, one column per zone, final prices.
zones = sorted(old.ZONES)
grid = {}
for band, lo, hi, m in old.BANDS:
    for z in zones:
        grid[(band, z)] = old.apply_remote_correction(z, band, old.ZONES[z] * m).quantize(Decimal("0.01"), rounding=old.ROUND_HALF_UP)

print("band,min_kg,max_kg," + ",".join(zones))
for band, lo, hi, m in old.BANDS:
    print(f"{band},{lo:g},{hi:g}," + ",".join(str(grid[(band, z)]) for z in zones))

def new_price(zone, w):
    for band, lo, hi, _ in old.BANDS:
        if lo <= w < hi:
            return grid[(band, zone)]
    raise ValueError

rows = list(csv.DictReader(open(sys.argv[2])))
mism = []; total_old = total_new = Decimal(0); used = collections.Counter()
for r in rows:
    w = float(r["weight_kg"]); a = old.price(r["zone"], w); b = new_price(r["zone"], w)
    total_old += a; total_new += b; used[(old.band_for(w), r["zone"])] += 1
    if a != b: mism.append((r["order_id"], a, b))
print(len(rows), "orders;", len(mism), "mismatches; totals", total_old, total_new)
print("cells used:", len(used), "of", len(grid))
print("surcharged orders:", sum(n for (b, z), n in used.items() if z in old.REMOTE_ZONES and b in old.HEAVY_BANDS))
EOF
